#include <iostream>
#include <string>

using namespace std;

int main() {
    string s;
    cin >> s;

    int ans = 0;
    for (char c : s) {
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' ||
            (c >= '0' && c <= '9' && (c - '0') % 2 == 1)) {
            ans++;
        }
    }

    cout << ans;
    return 0;
}

